import unittest
from view import greeting

class GreetingTests(unittest.TestCase):
    def test_greeting(self):
        self.assertEqual(greeting("Alice"), "Hello, Alice!")
        self.assertEqual(greeting("Bob"), "Hello, Bob!")

if __name__ == "__main__":
    unittest.main()

